insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 1, 'What does the soft-string model give the drill string?', '["Bending stiffness only.", "Weight and axial stiffness, and no bending stiffness at all.", "Weight, axial stiffness and bending stiffness, with the bending term linearised about the local hole curvature.", "Weight alone, since a cable model has no stiffness of any kind in either the axial or the bending direction."]'::jsonb, 1, 'It keeps the consequence of the bend, which is that tension pulls the string against the wall, and drops the resistance to being bent.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 2, 'Why is treating a drill string as a rope a reasonable pretence?', '["Because the pipe is thin and the hole is long, so the bending moment is small next to tension times curvature.", "Because drill pipe is genuinely flexible.", "Because the bending stiffness cancels out of the equations once the string is fully immersed in a single fluid.", "Because the model is only used on vertical wells, where there is no curvature for a stiffness term to act on."]'::jsonb, 0, 'A 5 inch pipe in a 3 degrees per 30 m build is bent to a radius of about 570 m, and over a 10 m interval it deflects a few centimetres.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 3, 'What is the structural relationship between torque and drag?', '["They are two separate calculations.", "Drag is the axial part of the weight and torque is the rotational part, so both come from the string''s own mass.", "They are two components of one friction force resolved in two directions.", "Torque is computed from drag by multiplying by the tool joint radius, which is why the two always move together."]'::jsonb, 2, 'Both come from the same normal force, and one pair of direction cosines decides how it is shared.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 4, 'What does the buoyancy factor equal in this course''s mud?', '["About 0.18, the density ratio.", "It depends on the string''s cross-sectional area, since buoyancy is a force on the displaced volume rather than a factor.", "About 0.5, because the mud supports roughly half the string''s weight in a hole of this diameter.", "About 0.8166, from one less 1440 divided by 7850."]'::jsonb, 3, 'It is a factor rather than a force because it applies to every metre identically, which is only true with one fluid inside and out.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 5, 'Where does buoyancy stop being a single factor?', '["When the string has different fluids inside and outside it, as a completion string does.", "When the mud weight changes with depth.", "When the hole is deviated, because then the buoyed weight has to be resolved along the hole rather than vertically.", "When the string is in compression, because the buoyed weight then acts in the opposite direction to the tension."]'::jsonb, 0, 'That is one of the effects this engine does not model, and it is why completion string analysis uses a different tool.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 6, 'What is drag, in this model?', '["The resistance of the mud to the string moving.", "The axial friction force between the string and the hole, opposing whatever the string is doing.", "The difference between the string''s weight in air and its weight in mud, which is what the buoyancy factor gives.", "The force required to overcome the bit''s resistance to turning, transmitted up the string as an axial load."]'::jsonb, 1, 'It fights you on the way out and helps hold the string up on the way in, which is why pick up and slack off differ.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 7, 'People expect the model to do one of these. Which does it not do?', '["A steady-state calculation.", "A calculation of the tension and torque along a string, from which a separate check compares against pipe ratings.", "A stress analysis of the pipe.", "A model with one calibrated constant in it, that constant being the friction factor applied at every contact."]'::jsonb, 2, 'It gives the loads. Whether the pipe will fail is a separate calculation with its own standards and safety factors.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 8, 'What is the vertical well''s hookload, in closed form?', '["The air weight of the whole string.", "The buoyed weight less the friction in the cased section, which is the only section generating side force in a vertical hole.", "The buoyed weight resolved along the hole, which in a vertical well is smaller than the total by the cosine of the inclination.", "The buoyed weight of the whole string."]'::jsonb, 3, 'No curvature and no inclination means no side force, so no friction, whatever the friction factor is set to.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 9, 'Why does a torque and drag run matter while drilling rather than only while planning?', '["Because the difference between predicted and measured hookloads is an early warning about hole condition.", "Because the rig contract requires it daily.", "Because the model has to be re-run at every connection in order to keep the friction factor from drifting out of date.", "Because the survey changes as the well is drilled, and the model is the only place the new survey is used."]'::jsonb, 0, 'A model calibrated on the first thousand metres becomes a monitor for the next three thousand, which is worth more than the planning use.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 10, 'What does a collision between a computed and a measured hookload most often indicate?', '["The survey tool has failed.", "Something has changed in the hole: cuttings, a ledge, sticking or a washout.", "The buoyancy factor is wrong, since it is the only term that applies uniformly to every metre of the string.", "The rig''s weight indicator needs recalibrating, which is the commonest cause of a systematic offset in the readings."]'::jsonb, 1, 'The rock did not change. What changed is something the model cannot see, and the friction factor is the summary statistic for all of it.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 11, 'Which uses of the model need a CHANGE in hookload rather than an absolute one?', '["Specifying the derrick rating.", "Checking whether the casing string will reach bottom, which depends on the total load at the top of the string.", "Monitoring hole condition while drilling.", "Deciding whether the top drive can supply the torque required at total depth, which is an absolute comparison."]'::jsonb, 2, 'The absolute number sets ratings and the difference carries the diagnosis, and confusing the two changes how much the friction factor''s error matters.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 12, 'What is a rule of thumb for when soft string is furthest from the truth?', '["Severe doglegs, short stiff components, and a pipe large relative to the hole.", "Long vertical sections.", "High mud weights, where the buoyancy factor is smallest and the string''s effective weight is most reduced by the fluid.", "High rotary speeds, where the tangential velocity dominates the direction cosines and the axial friction is small."]'::jsonb, 0, 'Drill collars in a tight build are the worst case; drill pipe in a gentle build is where soft string is closest.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 13, 'Why is the model not a dynamic one?', '["Because dynamics need a finer step.", "It computes a steady state, so stick-slip, whirl and axial oscillation are all outside it.", "Because dynamic loads are always smaller than static ones, so a steady-state answer is conservative by construction.", "Because the rotary speed is an input rather than a result, which fixes the dynamics before the calculation begins."]'::jsonb, 1, 'Every one of those makes the real loads higher than the computed ones, sometimes by a large factor.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 14, 'What decides whether a well can be drilled at all, in this model''s terms?', '["Whether the trajectory closes geometrically.", "Whether the derrick can lift the string, which is the load the rig contract is written against and the usual constraint.", "Whether the buoyancy factor is high enough that the string''s weight stays within the pipe''s tensile rating.", "Whether the string reaches bottom and the torque stays below what the drive can supply."]'::jsonb, 3, 'A trajectory that closes geometrically can still be undrillable, and that check is what this course adds to the survey one.'),
  ('torquedrag', 'beginner', 'module', 'm01-what-torque-and-drag-is', 15, 'What is the buoyancy factor at zero mud density?', '["Exactly 0.", "Undefined, since the formula divides by the mud density and a zero density makes the expression singular.", "Exactly 1.", "It depends on the steel density chosen, which is 7850 kg/m3 by default and can be overridden per component."]'::jsonb, 2, 'One less zero over 7850. The string weighs its air weight, which is the obvious sanity check on the formula.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 1, 'Where does side force come from, in a curved hole?', '["The mud pressure acting on the pipe.", "The bending moment the pipe develops as it is forced to conform to the hole''s curvature over the interval.", "The tension in the string, pulled around the corner by the curvature.", "The weight of the string above, transmitted down through the connections to the point where the hole bends."]'::jsonb, 2, 'Exactly as a rope around a bollard presses on the bollard. The size is the tension times the angle turned through.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 2, 'Side force from curvature is a product of what two things?', '["Tension and curvature, so both have to be present for it to be nonzero.", "Weight and inclination.", "Tension and interval length, so a longer interval always produces more side force at the same tension level.", "The friction factor and the normal force, which is the definition of a Coulomb friction force in this model."]'::jsonb, 0, 'A straight hole under enormous tension produces nothing, and a slack string in a sharp dogleg produces nothing either.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 3, 'What is the second source of side force?', '["The bit''s reaction to weight on bit.", "The mud''s drag on the outside of the pipe, which acts perpendicular to the hole wherever the string is moving.", "The centrifugal force from rotation, which presses the string outward against the wall at high rotary speeds.", "The component of the string''s weight perpendicular to an inclined hole."]'::jsonb, 3, 'It scales as the sine of the inclination: zero in a vertical hole and the full buoyed weight in a horizontal one.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 4, 'Why does a vertical well have no drag at all?', '["Because the friction factor is zero there.", "Both sources of side force vanish: no curvature, and sin(0) is zero.", "Because the string hangs in the centre of the hole and never touches the wall at any point along its length.", "Because the buoyancy factor supports the whole weight, so there is nothing left to press against the wall."]'::jsonb, 1, 'With no normal force there is no friction, whatever the friction factor is. Set it to 0.9 and nothing changes.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 5, 'In a straight horizontal lateral, what is the side force per metre?', '["Zero, since the hole is straight.", "The buoyed weight per metre times the friction factor, since friction is what presses the string into the wall.", "The buoyed weight per metre of whatever component is there.", "The tension times the curvature, which in a straight section is evaluated at the local dogleg severity of the survey."]'::jsonb, 2, 'Curvature is zero and the sine of ninety degrees is one, so the whole buoyed weight presses on the low side.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 6, 'Why does the calculation march UP from the bit?', '["Because the bit is where the boundary condition is known.", "Because tension is largest at the top.", "Because friction acts upward while tripping in, so the recursion has to run in the direction friction acts.", "Because the survey is indexed from the bit upward, which is how a station list is stored in this engine."]'::jsonb, 0, 'Marching down from surface would need a guessed hookload and an iteration; marching up from a known bit condition is one pass.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 7, 'What is the tension at the bit for a tripping operation?', '["Minus the weight on bit.", "Zero, because the string is hanging free.", "The buoyed weight of the bottom hole assembly, which is the part of the string below the last stabiliser.", "The bit torque divided by the tool joint radius, which converts the rotational boundary condition into an axial one."]'::jsonb, 1, 'For an on-bottom operation it is minus the weight on bit instead, and the torque starts at the bit torque rather than zero.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 8, 'What do the two direction cosines do?', '["Convert degrees into radians.", "Resolve the string''s weight into a component along the hole and a component perpendicular to it at each station.", "Scale the tool joint radius so that the moment arm matches the contact point rather than the pipe body centre.", "Split one friction force between the axial and the tangential directions."]'::jsonb, 3, 'That single pair produces every difference between the six operations in this course, and their squares sum to one.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 9, 'Which term is absent from the torque recursion but present in the tension one?', '["The weight term.", "The friction term.", "The direction cosine, which appears only in the axial equation because torque is a moment rather than a force.", "The interval length, since torque accumulates per revolution rather than per metre of measured depth."]'::jsonb, 0, 'Weight adds to tension every interval and adds to torque only through the side force it produces, which is why a vertical torque profile is flat.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 10, 'What does the soft-string model do at a dogleg that a real stiff string does not?', '["It ignores the dogleg entirely.", "It adds a bending moment at each end of the dogleg, which raises the contact force above the smeared value.", "It spreads the contact force smoothly instead of concentrating it at tangency points.", "It refuses to compute, because a dogleg past a threshold severity is outside the model''s stated range of validity."]'::jsonb, 2, 'The total is similar and the distribution is not, and the distribution is what matters for wear, local buckling and fatigue.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 11, 'What is the only numerical knob in the model?', '["The number of bisection halvings.", "The integration step, which defaults to 10 m.", "The convergence tolerance on the tension recursion, which is iterated to a residual at each interval before moving on.", "The survey interpolation method, which can be minimum curvature or spherical linear interpolation of the tangents."]'::jsonb, 1, 'Everything else is closed-form arithmetic on each interval. The step is where the approximation lives.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 12, 'When does the step size matter?', '["Always, by roughly the same amount.", "In long vertical sections, where there are many intervals and the discretisation error accumulates over all of them.", "At high rotary speeds, where the tangential velocity dominates and the direction cosines change rapidly per interval.", "Where the string is in compression, near a sign change, or near a buckling threshold."]'::jsonb, 3, 'On a slant well rotating on bottom the hookload moves less than a newton across a fortyfold refinement. On a horizontal well in compression it moves a kilonewton.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 13, 'What does the midpoint tension predictor buy?', '["Second-order rather than first-order accuracy in the recursion.", "A guaranteed convergence.", "The ability to handle a sign change in the tension without the calculation becoming singular at the crossing.", "A correct treatment of the boundary condition at the bit, which the endpoint formulation would get wrong."]'::jsonb, 0, 'Using the end-point tension would make the recursion first-order. The predictor uses the tension halfway through the interval instead.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 14, 'Which of these is NOT among the effects the model omits?', '["Static versus kinetic friction.", "Piston forces at diameter changes and the ballooning from the pressure differential across the pipe wall.", "The change in tension along the string from its own weight.", "Stick-slip, whirl, and the axial oscillation that makes the instantaneous weight on bit swing about its mean."]'::jsonb, 2, 'The weight term is the core of the model. The other three are all real, all absent, and all make the real loads higher than the computed ones.'),
  ('torquedrag', 'beginner', 'module', 'm02-the-soft-string-model', 15, 'What should you do before relying on a torque and drag number?', '["Increase the friction factor by ten percent.", "Refine the step once and confirm the answer moved by less than you care about.", "Compare it against the oracle values in the goldens, which are available for every well and every operation in the fixture set.", "Run every operation on the same well, so that the internal consistency of the six answers can be checked against each other."]'::jsonb, 1, 'It costs one extra run and it is the only honest way to know that the discretisation is not the thing you are reading.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 1, 'What are the three hookloads a driller records at a connection?', '["Maximum, minimum and mean.", "Pick up, rotate off bottom, and slack off.", "Pick up, slack off, and the hookload with the pumps off, which removes the pump-open force from the reading.", "Rotating on bottom, rotating off bottom, and sliding, which are the three states the string is actually drilled in."]'::jsonb, 1, 'Pick up is always the largest and slack off the smallest, with rotating between them, and that order falls out of the sign of the axial friction.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 2, 'Why is the rotating-off-bottom hookload not the string''s buoyed weight?', '["Because part of the weight is carried by the wall, so what the string above carries is the integral of w cos(theta).", "Because rotation lifts the string.", "Because the tangential friction has an axial component at any inclination other than exactly vertical or horizontal.", "Because the bit torque is applied at the bit and propagates upward as an axial load through the string."]'::jsonb, 0, 'In a vertical well the two are equal because the cosine is one. On a 40 degree slant they are substantially different.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 3, 'Why are the pick-up drag and the slack-off drag not equal?', '["Because the friction factor differs.", "Because the trip speed is different in the two directions, and the direction cosines depend on the axial velocity.", "Because the tension differs, and the tension is part of what produces the side force.", "Because the weight on bit is applied while tripping in and released while tripping out, changing the boundary condition."]'::jsonb, 2, 'Tripping out puts more tension in the string, which presses it harder into every curve, which makes more friction. That feedback is why the model is a recursion.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 4, 'On the horizontal well, which is larger: pick-up drag or slack-off drag?', '["Pick-up drag, as on every well.", "They are equal, because the same friction factor acts on the same side force in both directions of travel.", "It depends on the trip speed, which sets how much of the friction goes into the axial direction in each case.", "Slack-off drag, which reverses the usual ordering."]'::jsonb, 3, 'The tidy ordering people carry in their heads is a property of moderately deviated wells rather than a law.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 5, 'Why should the DIFFERENCE be used rather than the absolute hookload when tracking hole condition?', '["Because the absolute value grows every connection as the string lengthens, which swamps the signal.", "Because differences are easier to measure.", "Because the absolute value depends on the buoyancy factor, which changes whenever the mud weight is adjusted at surface.", "Because the derrick rating is set from the absolute value, so using it for monitoring would confuse two separate purposes."]'::jsonb, 0, 'The absolute value is what sets ratings. The difference is what carries the diagnosis.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 6, 'What does the broomstick plot show?', '["Hookload against time during a trip.", "Tension against depth for pick up, rotating and slack off, on one chart.", "The three hookloads at each connection, plotted against the depth at which each connection was made during drilling.", "The side force per metre for each of the three operations, which is where the fan between the three curves comes from."]'::jsonb, 1, 'The three curves start together at the bit and fan apart going up, like the bristles of a broom.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 7, 'Where do the three broomstick curves separate?', '["At the casing shoe, always.", "At the kick-off point, because that is where the well first departs from vertical and the friction factor changes.", "Exactly where there is side force, and nowhere else.", "Where the string composition changes, because the three curves have different slopes in each component."]'::jsonb, 2, 'In a section with no side force all three gain tension at the same rate. The gradient of the gap is the local friction contribution.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 8, 'What does the horizontal well''s negative slack-off hookload mean?', '["The weight indicator is reading wrongly.", "The string is being lifted by the mud''s buoyancy, which at this angle exceeds the steel''s own weight per metre.", "The hook is supporting the string from below, which is what happens when a tractor is run on the bottom hole assembly.", "The friction holding the string up exceeds its own weight resolved along the hole."]'::jsonb, 3, 'The hook would have to pull DOWN to make the string descend at 0.3 m/s, and a drill string cannot be pushed.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 9, 'What actually happens on the rig when the model returns a negative slack-off hookload?', '["The string stops, having buckled into a sine wave and then a helix.", "The hook applies a downward force.", "The driller increases the mud weight, which raises the buoyancy factor and reduces the friction along the lateral.", "The string descends more slowly, because the trip speed adjusts until the friction and the weight balance each other."]'::jsonb, 0, 'Once helical the pipe presses outward hard, which increases the friction, which requires more push, which buckles it further. That is lock-up.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 10, 'What is the right response to a negative slack-off hookload?', '["Refine the integration step.", "Change the physical problem: heavier pipe, a tractor, a friction reducer, or a shorter lateral.", "Lower the friction factor in the model until the number goes positive, then use that factor for the rest of the well.", "Accept the number and run the string anyway, since a negative hookload simply means the string goes in without assistance."]'::jsonb, 1, 'The model is telling you the physical problem needs to change. Adjusting the model until the answer is comfortable is the failure mode.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 11, 'In a vertical well, how do the three hookloads compare?', '["Pick up is about ten percent higher.", "They differ only in the cased section, where the friction factor of 0.25 acts on the string''s weight against the casing.", "Identical to the last digit, because there is no side force anywhere.", "Rotating is the smallest, because the tangential friction reduces the axial load the string above has to carry."]'::jsonb, 2, 'That is a unit test you can run in your head, and software that fails it has a bug in the side-force calculation.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 12, 'What does the model report about the vertical well while rotating on bottom?', '["No warnings at all.", "A torque well above the bit torque, because the compression from the weight on bit generates side force near the bit.", "A hookload equal to the buoyed weight, since the weight on bit is applied at the bit and does not reach surface.", "Buckling from the depth where the tension crosses zero."]'::jsonb, 3, 'The buckling limits are exactly zero at zero inclination, so any compression at all trips the flag. It is correct and it needs interpretation.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 13, 'Which of the three drag differences is the total swing?', '["Pick up less slack off.", "Pick up less rotating.", "Rotating less slack off, which is the part of the drag that friction contributes while the string is going down.", "The larger of the pick-up drag and the slack-off drag, since the swing is the worst case of the two."]'::jsonb, 0, 'It is the sum of the two individual drags, so a report quoting drag without saying which is ambiguous by up to a factor of two.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 14, 'A colleague reads a shape off the plot and infers the hole''s geometry. What is wrong?', '["Where the drag is being generated.", "What the hole looks like, since two very different geometries can give similar curves.", "The tension at any depth, which requires the profile rather than the summary numbers the plot is built from.", "Whether the string is in compression anywhere, which needs the zero line the chart does not draw."]'::jsonb, 1, 'It is a picture of the tension in a string that is currently in the hole, computed on assumptions. The survey listing is where the geometry lives.'),
  ('torquedrag', 'beginner', 'module', 'm03-hookload', 15, 'Why does the pick-up hookload eventually stop rising as a well is deviated further?', '["Because the friction factor falls at high angle.", "Because the drag saturates once the string is fully in contact with the low side over its whole length.", "Because more of the string''s weight is carried by the wall as the cosine falls.", "Because the buoyancy factor rises with inclination, which reduces the effective weight of the string in the hole."]'::jsonb, 2, 'On the slant well pick up exceeds the buoyed string weight and on the build-and-hold well it does not, which is that crossover.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 1, 'What three columns distinguish the six operations?', '["Axial velocity, rotation, and whether the bit is on bottom.", "Depth, inclination and azimuth.", "Trip speed, rotary speed and weight on bit, which are the three numbers a driller sets at the console for each operation.", "Friction factor, buoyancy factor and integration step, which are the three inputs that change between the six runs."]'::jsonb, 0, 'Everything else, the string, the hole, the mud and the friction factors, is identical between them.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 2, 'What does being on bottom change in the calculation?', '["The friction factor in the open hole.", "The direction cosines, because the bit''s rotation adds a tangential velocity the string above the motor does not have.", "Two boundary conditions at the bit: tension starts at minus the weight on bit, and torque at the bit torque.", "The step size, which the engine reduces near the bit so that the compression there is resolved more finely."]'::jsonb, 2, 'There is no extra physics. The bit is a place where a known force and a known moment are applied.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 3, 'Why does tripping produce no torque at all?', '["Because the bit is off bottom.", "With no rotation the tangential velocity is zero, so the tangential direction cosine is zero.", "Because the torque recursion has no weight term, and while tripping the weight is the only load acting on the string.", "Because the drawworks rather than the top drive is supplying the motion, and only the top drive can apply a moment."]'::jsonb, 1, 'All the friction is axial. There is nothing for the tangential component to act on.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 4, 'Why does rotating off bottom give the free-hanging hookload?', '["Because rotation lifts the string.", "Because the bit is off bottom, so there is no weight on bit to subtract from the load the string carries.", "Because rotating averages the friction around the circumference, so its net axial contribution integrates to zero.", "The axial velocity is zero, so the axial direction cosine is zero and the axial friction vanishes."]'::jsonb, 3, 'It is the integral of the buoyed weight resolved along the hole, which is not the same as the total buoyed weight in a deviated well.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 5, 'What does sliding produce at surface, in terms of torque?', '["Zero, since the string does not rotate.", "The bit torque plus the friction torque in the section below the motor, which is the only rotating part of the assembly.", "Exactly the bit torque, because nothing above the motor is turning.", "The same torque as rotating off bottom, since the friction along the string is unchanged by the mode of drilling."]'::jsonb, 2, 'That is true on every well in this course, and it is why a downhole torque measurement is worth so much more while sliding.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 6, 'What makes sliding hard in a horizontal well?', '["Weight transfer: friction in the lateral eats the load before it reaches the bit.", "The mud motor stalls at low weight.", "The bit torque is applied without any rotation above it, which winds the string up and stores energy in it.", "The trip speed is fixed at 0.3 m/s, which is too fast to allow the assembly to build angle in a soft formation."]'::jsonb, 0, 'On four of the five wells the minimum tension while sliding is exactly the weight on bit. On the horizontal well it is nearly five times that.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 7, 'What does rocking the string while sliding achieve?', '["It reduces the total friction force.", "It converts most of the axial friction into tangential friction through the direction cosines.", "It keeps the bit turning during the slide, which is what the mud motor would otherwise have to do on its own.", "It cleans the hole, which lowers the friction factor and therefore the axial resistance to weight transfer."]'::jsonb, 1, 'The friction magnitude is unchanged. What changes is which direction it acts in, and only the axial part fights weight transfer.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 8, 'What is back reaming?', '["Running in while rotating.", "Reaming a tight spot on the way in, which is the same operation with the axial direction reversed and the pumps off.", "Rotating off bottom with the pumps on, which circulates the hole clean without moving the string axially at all.", "Pulling out of the hole while rotating."]'::jsonb, 3, 'Both velocities are nonzero, so the friction is shared between the axial and tangential directions.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 9, 'At 120 rpm and 0.3 m/s, roughly how is the friction shared while back reaming?', '["Evenly between the two.", "Almost all of it axially, because the trip speed is the dominant motion and the rotation contributes very little.", "About a quarter axially and almost all of it tangentially.", "It depends on the friction factor, which sets how much of the normal force becomes a friction force in each direction."]'::jsonb, 2, 'The tool joint''s surface speed at 120 rpm is about three and a half times the trip speed, so the sliding direction is nearly tangential.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 10, 'What does back reaming trade?', '["Drag for torque, at a rate the driller sets through the trip speed.", "Torque for drag.", "Rig time for hole cleaning, since a slower trip removes more cuttings from the annulus per metre of hole.", "Casing wear for hookload, since rotating in casing takes metal off it while reducing the load on the derrick."]'::jsonb, 0, 'The casing wear point is a real cost and it is a consequence rather than the trade. The trade is between the drawworks and the top drive.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 11, 'Why does back reaming reduce the hookload a lot and raise the torque very little?', '["Because torque is measured less accurately.", "The tangential cosine was already near one, so it barely changes, while the axial one goes from zero.", "Because the moment arm is the tool joint radius, which is small, so the same friction produces little torque and much drag.", "Because the hookload includes the string''s weight while the torque does not, so the same change is a larger fraction of one."]'::jsonb, 1, 'The asymmetry is entirely because the tool joint surface speed is three and a half times the trip speed.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 12, 'Which two operations differ by exactly the weight on bit on any well?', '["Tripping out and tripping in.", "Sliding and tripping in, because both move down at the same speed and only one has weight applied at the bit.", "Back reaming and tripping out, because both move up at the same speed and only one of the two is rotating.", "Rotating off bottom and rotating on bottom."]'::jsonb, 3, 'With zero axial velocity the axial cosine is zero, so the offset propagates up an axially frictionless string unchanged.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 13, 'Does tripping faster change the drag, in this model?', '["Yes, roughly in proportion to the speed.", "Yes, because the direction cosines depend on the ratio of the two velocities and the tangential one is zero.", "No: with no rotation the axial cosine is one for any nonzero speed.", "Only above a threshold speed, beyond which the friction transitions from a static to a kinetic regime."]'::jsonb, 2, 'That is a genuine limitation: real friction has a velocity dependence and surge and swab pressures are strongly speed dependent, and neither is here.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 14, 'What does the model do at exactly zero trip speed with no rotation?', '["Returns zero friction, so the hookload is the free-hanging weight.", "Refuses to run.", "Uses the static friction coefficient, which is higher than the kinetic one and which the engine carries separately.", "Holds the previous operation''s friction, since a stationary string retains whatever load it was left with."]'::jsonb, 0, 'That is a defensible convention and it is not what a real string does. The gap is what a driller feels when a string will not break over.'),
  ('torquedrag', 'beginner', 'module', 'm04-the-operations', 15, 'Which risks does the back-reaming calculation not price?', '["The load on the drawworks.", "Packing off the annulus, casing wear, and enlarging soft formations.", "The torque at the top drive, which is the constraint back reaming actually trades against and which the model omits.", "The reduction in hookload, which is the whole benefit and which the model computes only approximately."]'::jsonb, 1, 'So a back-reaming hookload that looks comfortable is not by itself a reason to back ream.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 1, 'What does the model return per grid point?', '["Only the hookload and the torque.", "The position of the string in three dimensions, from which the contact with the wall is then determined geometrically.", "Depth, inclination, tension, torque, side force, buckling state and utilization.", "The friction force and its two components, from which the tension and torque summaries are computed afterwards."]'::jsonb, 2, 'The summary numbers are the top row of that profile. Everything interesting is in between.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 2, 'What shape does the tension profile take in a vertical hole?', '["Three straight segments, one per string component, steepest at the bottom.", "A single straight line.", "A curve, because the buoyed weight per metre changes continuously with the mud''s density gradient down the hole.", "A straight line with a step at the casing shoe, where the friction factor changes from 0.25 to 0.35."]'::jsonb, 0, 'The slope is the buoyed weight per metre, and it changes only where the composition changes: collars, heavy weight and drill pipe.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 3, 'In a horizontal lateral tripping out, what is the tension gradient?', '["The buoyed weight per metre.", "The drag, because the weight contributes nothing when the cosine is zero.", "Zero, since there is no weight component along the hole and friction acts perpendicular to the string''s motion.", "The buoyed weight per metre times the friction factor, which is the side force each metre generates."]'::jsonb, 1, 'That is the single most useful thing to see on the profile: in a lateral, the tension gradient IS the drag.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 4, 'What is the force neutral point?', '["Where the hookload is zero.", "Where the buoyed weight of the string below equals the weight on bit, which is a fixed depth for a given assembly.", "Where the stress in the pipe equals the hydrostatic stress from the mud, so the pipe carries no axial load.", "Where the axial tension is zero."]'::jsonb, 3, 'The last of those is the STRESS neutral point, which is a different definition at a different depth, and both are in common use.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 5, 'Why is the neutral point a property of the operation rather than of the well?', '["Because friction changes the tension gradient, so it moves with what the string is doing.", "Because the survey changes as drilling proceeds.", "Because the mud weight is adjusted through the well, and the buoyancy factor sets where the compression begins.", "Because the weight on bit is a design parameter that is fixed before drilling and not changed afterwards."]'::jsonb, 0, 'Tripping out on a well with no compression there is no neutral point at all. Rotating on bottom on the same well there is.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 6, 'Where does the traditional drill collar rule come from, and where does it fail?', '["From horizontal wells, and it fails in vertical ones.", "From an API standard that predates deviated drilling, and it fails whenever the mud weight exceeds about 1500 kg/m3.", "From vertical wells, where compression comes only from weight on bit; it fails in horizontal wells.", "From the buckling limits, which are zero in a vertical hole, and it fails wherever the limits become nonzero."]'::jsonb, 2, 'In a horizontal well compression is generated by drag along the lateral, and no amount of collar at the bit removes it.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 7, 'What does the warning naming a buckling depth actually tell you?', '["That the string has failed.", "That the friction below that depth is an underestimate, and how far past the limit the string has gone.", "That the calculation could not converge below that depth and the results there should be discarded entirely.", "That the compression exceeds the pipe''s yield strength, so the pipe would deform permanently at that point."]'::jsonb, 1, 'The model does not change the friction when it detects buckling, so its answers past the limit are optimistic.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 8, 'Why does the vertical well trip a buckling flag while rotating on bottom?', '["Because the collars are too light.", "Because rotating adds a tangential load that combines with the axial compression to exceed the combined limit.", "Because the step size at 10 m is too coarse to resolve where the compression actually begins near the bit.", "Because the buckling limits at zero inclination are exactly zero, so any compression trips it."]'::jsonb, 3, 'It is a real property of the formula rather than a bug, and it is describing drill collars doing exactly what collars are for.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 9, 'What does the warning about hole geometry not covering the string mean?', '["The engine used a friction factor of zero in the uncovered interval, which is a setup error.", "The survey does not reach total depth.", "The string extends below the last casing shoe, which is normal and the warning can safely be ignored.", "The geometry sections overlap, so the engine had to choose one arbitrarily at each integration interval."]'::jsonb, 0, 'A zero friction factor is not conservative, it is silently optimistic, and the run is meaningless in that interval.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 10, 'What is the vertical well''s hookload equal to, and why does that matter?', '["The air weight, which needs no engine run.", "The buoyed weight less the friction in the cased section, which can be computed by hand from the casing length.", "The buoyed weight of the string, and it is the only closed-form answer in the course.", "The buoyed weight times the cosine of the average inclination, which is one in a vertical hole and less otherwise."]'::jsonb, 2, 'Sum the mass, multiply by gravity, multiply by the buoyancy factor. It is a hand calculation.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 11, 'What does the closed-form check establish about the two implementations?', '["That both are equally accurate.", "That the engine reproduces it to nanonewtons while the oracle is tens of newtons away.", "That the oracle is more accurate, since it uses a fourth-order scheme against the engine''s midpoint predictor.", "That the difference between them is discretisation, which refining the step in either would remove."]'::jsonb, 1, 'Two implementations agreeing tells you they agree. A closed form tells you which of them is closer.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 12, 'What does the vertical case NOT exercise?', '["The buoyancy factor.", "The string composition lookup, since a vertical well uses only the drill pipe over most of its length.", "The integration grid, because with no friction the recursion reduces to a single closed-form evaluation.", "The friction terms, the curvature terms and the direction cosines."]'::jsonb, 3, 'It is a necessary check and not a sufficient one, which is why the Professional tier has a whole module on the comparison.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 13, 'What is the right general habit the vertical case illustrates?', '["Run the degenerate case with a known answer first, before trusting anything interesting.", "Always use the finest step available.", "Always compare against an independent implementation, since a closed form is not available on a real survey.", "Always check the buckling flags first, since they indicate whether the model has left its domain of validity."]'::jsonb, 0, 'It costs one run, it exercises the whole input path, and it catches unit, sign and setup errors before the interesting cases are trusted.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 14, 'Which column of a torque and drag profile is NOT a computed result?', '["The side force per metre.", "The utilization, which is a ratio of the computed load against a rating supplied with the string description.", "The measured depth.", "The buckling state, which is a comparison of the computed compression against a limit derived from the geometry."]'::jsonb, 2, 'Depth and attitude come from the survey. Everything else in the row is arithmetic on them plus the friction factor.'),
  ('torquedrag', 'beginner', 'module', 'm05-reading-the-output', 15, 'Why is the tension profile not a stress profile?', '["Because tension is measured and stress is not.", "Because stress needs the area, plus a bending stress this model does not compute, plus the torsional stress.", "Because the profile is reported per grid point rather than per joint, and stress is a property of a joint of pipe.", "Because the model works in newtons rather than pascals, and the conversion needs a wall thickness that varies."]'::jsonb, 1, 'The utilization ratio is the closest the model gets, and even that is a simple ratio against a rating rather than a combined-loading check.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 1, 'After the Associate tier, what work can you honestly say you are able to do?', '["Design a well trajectory from scratch.", "Say what the friction factor absorbed and what a fitted value would predict for an observation you did not fit to.", "Compute what the hook will read for any of six operations on a stated hole and string.", "Judge whether the pipe will buckle, and what the resulting side force does to the casing it is turning against."]'::jsonb, 2, 'The other two are the Professional and Expert tiers. This one is the calculation both of them build on.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 2, 'What single sentence summarises this tier?', '["A hookload is a weight plus a friction force, and the friction is the hole''s shape times one chosen constant.", "A hookload is the weight of the string.", "A hookload is what the derrick reads, and the difference between the reading and the model is the hole''s condition.", "A hookload is the buoyed weight of the string resolved along the hole, which is what the model computes directly."]'::jsonb, 0, 'The next tier is entirely about that chosen constant, and everything this tier established feeds into it.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Which of these is the closed-form case this tier keeps returning to?', '["The horizontal well sliding.", "The build-and-hold well rotating on bottom, which is the only case where the side force can be integrated analytically.", "The slant well tripping in, because a constant tangent has a uniform side force that integrates to a simple expression.", "The vertical well tripping out."]'::jsonb, 3, 'No curvature and no inclination means no side force, so the hookload is the buoyed weight and a calculator settles it.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 4, 'What did this tier take entirely as given?', '["The survey and the string description.", "The friction factors, 0.25 cased and 0.35 open hole, with no discussion.", "The buoyancy factor, which was derived from the mud density and the steel density in the first module of the tier.", "The six operations, which were defined by the two velocity components and the bit boundary conditions."]'::jsonb, 1, 'That is the next tier''s whole subject: where those numbers come from, what they absorb, and what a fitted one hides.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What is the correct order of pick up, rotate and slack off?', '["Rotating largest, then pick up, then slack off.", "Slack off largest, because the string''s weight and the friction both act downward while it is being run in.", "Pick up largest, rotating between, slack off smallest.", "It depends on the well, since on a horizontal well the ordering of the three reverses completely."]'::jsonb, 2, 'That ordering comes out of the sign of the axial friction term and it holds on every well. What reverses on the horizontal well is which DRAG is larger.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 6, 'What is the one numerical knob, and when does it matter?', '["The integration step, and it matters where the string is in compression.", "The friction factor, and it always matters.", "The survey interval, which sets how finely the hole''s curvature is resolved and therefore how much side force is seen.", "The number of bisection halvings in the friction solver, which sets the precision of a calibrated factor."]'::jsonb, 0, 'On a slant well rotating on bottom, refining fortyfold moves the hookload by less than a newton. On a horizontal well in compression it moves a kilonewton.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Which two things does the model NOT compute that people expect it to?', '["The tension and the torque.", "The side force and the buckling limits, both of which need the pipe''s bending stiffness that soft string discards.", "The hookload and the surface torque, which need a boundary condition at surface the model does not have.", "A stress state in the pipe, and any dynamic effect."]'::jsonb, 3, 'It gives the loads; a separate pipe strength check compares them against ratings. And it computes a steady state, so stick-slip and whirl are outside it.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What does the capstone ask you to reproduce?', '["The surface torque on five wells.", "A buoyancy factor and five hookloads from three wells, at a mud weight the lessons did not use.", "The buckling limits, the two utilizations and the casing wear that the side forces produce over a rotating schedule.", "A friction factor fitted to an observed hookload, plus the torque that factor then predicts for the same well."]'::jsonb, 1, 'The other two are the Professional and Expert capstones, in that order, over the same five wells.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Why is the capstone run at a different mud weight from the lessons?', '["Because 1500 kg/m3 is the industry standard.", "Because the lessons'' mud weight produces buckling on several wells, which would make the answers ambiguous to grade.", "So that every graded value is one you produce rather than one a lesson printed.", "Because the buoyancy factor at 1440 has too few significant figures to support a tolerance of five parts in ten million."]'::jsonb, 2, 'It is also a real question somebody asks on a real well: what does a mud weight increase do to my torque and drag.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What should you carry from this tier into the next?', '["That every number is a geometry you can check times a constant somebody fitted.", "That the vertical well has no drag.", "That the step size matters most where the string is in compression, which is where the model is least reliable anyway.", "That pick up is always larger than slack off, which is the ordering the sign of the axial friction produces."]'::jsonb, 0, 'All three are true. The first is the one that changes how you read every report the model produces.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Why does a driller record three hookloads rather than one?', '["Because the rig contract requires all three.", "Because their differences track the hole''s condition while the absolute value only tracks the string''s length.", "Because the model needs all three as inputs in order to calibrate the friction factors in the two hole sections.", "Because each of the three is measured by a different instrument, and comparing them detects an instrument fault."]'::jsonb, 1, 'The absolute values drift as the string gets longer, and the drift swamps whatever you were trying to see.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What is the relationship between the six operations?', '["They are six separate calculations.", "They are three pairs, each pair differing only by whether the bit is on bottom, which changes the boundary condition.", "They are two families, tripping and rotating, with sliding and back reaming being special cases of the first.", "One pair of direction cosines and two bit boundary conditions produce all six from one model."]'::jsonb, 3, 'The cosines are set by the ratio of trip speed to tool joint surface speed, and everything else about the six follows from them.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What does a negative slack-off hookload tell a planner?', '["The model needs a finer step.", "The friction factor is too high and should be reduced until the answer becomes positive and physically plausible.", "The physical problem has to change: pipe, mud, a tractor or a shorter lateral.", "The string will descend more slowly than the assumed trip speed, and the calculation should be rerun at that speed."]'::jsonb, 2, 'The model is telling you it has left its own domain. Adjusting the model until the answer is comfortable is the failure mode.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which of these would a torque and drag run NOT settle?', '["Whether the hole will stand up at the planned mud weight.", "Whether the string reaches bottom.", "Whether the top drive can supply the torque needed at total depth, which is a comparison against a stated rating.", "Whether the derrick can lift the string on a routine trip out, which sets the rating in the rig contract."]'::jsonb, 0, 'That is a geomechanics question, and cuttings from a hole that does not stand up are one of the things the friction factor then absorbs.'),
  ('torquedrag', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Why does the course hold the string, mud and parameters fixed across five wells?', '["Because the goldens only carry one string.", "Because moving one thing at a time is the only way a difference in the answer means anything.", "Because a different string on each well would make the buoyancy factor differ, which would invalidate the comparison.", "Because the engine cannot change the string description between runs without recompiling the component lookup."]'::jsonb, 1, 'It also makes every number comparable across the whole course, which is why a hookload learned on one well can be set against another.'),
  ('torquedrag', 'beginner', 'final', null, 1, 'A junior engineer says the model computed a drag of 300 kN. What do you ask?', '["Which well it was computed on.", "Which two hookloads were subtracted, since there are three answers people call drag.", "What the friction factor was, since drag is proportional to it and the number is meaningless without the factor.", "Whether the number is the axial or the tangential component, since the model splits the friction between them."]'::jsonb, 1, 'Pick up less rotating, rotating less slack off, and pick up less slack off differ by up to a factor of two.'),
  ('torquedrag', 'beginner', 'final', null, 2, 'A vertical well''s model returns different pick-up and slack-off hookloads. What is wrong?', '["A bug: with no curvature and no inclination there is no side force and therefore no friction.", "Nothing, the mud weight differs.", "The friction factor in the cased section is being applied to the string''s weight against the casing wall.", "The trip speed is different in the two directions, which changes the direction cosines and therefore the drag."]'::jsonb, 0, 'It is a unit test you can run in your head, and it is the first thing to check on unfamiliar software.'),
  ('torquedrag', 'beginner', 'final', null, 3, 'You are told a well''s hookload will be 1.1 MN and the derrick is rated at 1.5 MN. What else do you need?', '["The torque at the same depth.", "The buoyancy factor, since the rating is quoted in air weight and the hookload is a buoyed value.", "The overpull margin you want above it, in case the string sticks.", "The step size the calculation used, since a coarse step can understate the hookload by a kilonewton or more."]'::jsonb, 2, 'The routine trip is not the design case. Pulling on a stuck string is, and it is limited by the pipe and the derrick together.'),
  ('torquedrag', 'beginner', 'final', null, 4, 'The slack-off hookload on a planned lateral comes out negative. What do you conclude?', '["The calculation has a sign error.", "The string will descend, more slowly than assumed, once the trip speed adjusts to balance friction against weight.", "The mud weight is too high, and reducing it will raise the buoyancy factor enough to make the number positive.", "The string will not go in under its own weight and the plan has to change."]'::jsonb, 3, 'Reducing the mud weight makes the string HEAVIER in the hole, which would help, and the size of the deficit is usually far beyond what mud can fix.'),
  ('torquedrag', 'beginner', 'final', null, 5, 'A colleague proposes back reaming a 4000 m lateral to reduce the pick-up hookload. What is your objection?', '["Back reaming does not reduce hookload.", "The hookload reduction is small, because at 120 rpm almost all of the friction is already in the axial direction.", "On a lateral it is torque, not hookload, that is close to a limit, and back reaming raises torque.", "The trip speed would have to be raised to make the trade worthwhile, and a faster trip generates surge pressures."]'::jsonb, 2, 'The trade is drag for torque, and it is a good trade only when the derrick is the constraint. On a lateral it is not.'),
  ('torquedrag', 'beginner', 'final', null, 6, 'You need to check an unfamiliar torque and drag package. What is the first case you run?', '["A vertical well, and compare the hookload against the string''s buoyed weight by hand.", "A horizontal well at high friction.", "A build-and-hold well, because it exercises both the curvature and the weight sources of side force at once.", "The most deviated well in your field, so that any error shows at its largest before you rely on the tool."]'::jsonb, 0, 'It costs one run, it exercises the whole input path, and it is the only case with an answer a third party can compute.'),
  ('torquedrag', 'beginner', 'final', null, 7, 'A model reports the same surface torque for tripping out and tripping in. Is that right?', '["No, torque should be larger going out.", "Yes, both are zero, because nothing is rotating in either case.", "Yes, because the same friction acts in both cases and torque does not depend on the direction of the axial motion.", "No, unless the well is vertical, where the absence of side force makes both the torque and the drag zero."]'::jsonb, 1, 'With rpm at zero the tangential direction cosine is zero, so there is no tangential friction and no torque at all.'),
  ('torquedrag', 'beginner', 'final', null, 8, 'Where in a build-and-hold well is the side force largest while tripping out?', '["At total depth.", "In the hold section, where the string lies against the low side over the greatest length of hole at high angle.", "At the casing shoe, where the friction factor steps from 0.25 to 0.35 and the side force jumps with it.", "Near the top of the build, where curvature is present and tension is highest."]'::jsonb, 3, 'Below the build the curvature is gone and above it both terms are zero, so the profile is a hump rather than a ramp.'),
  ('torquedrag', 'beginner', 'final', null, 9, 'Why does the model march up from the bit rather than down from surface?', '["Because the bit-end condition is known and the surface one is what you are solving for.", "Because friction acts upward.", "Because the survey is stored from total depth upward, so marching that way avoids reversing the station list.", "Because the tension is largest at surface, and integrating toward a large number is numerically better conditioned."]'::jsonb, 0, 'Marching down would need a guessed hookload and an iteration to hit a bit-end condition. Marching up is one pass.'),
  ('torquedrag', 'beginner', 'final', null, 10, 'A string description is entered without tool joint diameters. What happens?', '["Nothing, they are not used.", "The buckling limits are wrong, since the radial clearance is computed from the tool joint rather than the body.", "The torque comes out about a quarter low and the hookload is barely affected.", "The calculation refuses to run, because the engine needs a contact radius for every string component."]'::jsonb, 2, 'The engine falls back to the body diameter, and the tool joint radius is 1.325 times it, so the moment arm is 24.5 percent short.'),
  ('torquedrag', 'beginner', 'final', null, 11, 'A driller asks why rotating the string while pulling makes it lighter. What do you say?', '["Rotation reduces the contact force.", "The friction has not changed; most of it has moved from the axial direction into the tangential one.", "The rotation flings the string away from the wall, which reduces the normal force and therefore the friction.", "Rotation warms the mud, which lowers its viscosity and reduces the drag on the outside of the pipe."]'::jsonb, 1, 'The top drive is now paying for what the drawworks was paying for, and the sum of the two shares is conserved.'),
  ('torquedrag', 'beginner', 'final', null, 12, 'A well is planned with a 4 degree per 30 m build at 2500 m. What is the concern?', '["The build rate exceeds equipment limits.", "The dogleg will make the survey listing inaccurate, since minimum curvature is approximate at high severity.", "The build will be drilled by sliding, which on a deep well cannot transfer enough weight to the bit.", "The whole string above it pulls through that curvature, so the side force there is large."]'::jsonb, 3, 'Putting the same build shallower would put it where the tension is low, which is the whole reason to build early.'),
  ('torquedrag', 'beginner', 'final', null, 13, 'What does the model assume about friction that a real string does not obey?', '["That friction opposes motion.", "That friction is proportional to the normal force, which is the definition of Coulomb friction and holds well in practice.", "One coefficient, independent of sliding speed and identical whether the string is moving or stationary.", "That friction acts at the contact surface rather than at the pipe''s centreline, which is why the tool joint radius is used."]'::jsonb, 2, 'Real friction has a velocity dependence and a static coefficient higher than the kinetic one, and neither is here.'),
  ('torquedrag', 'beginner', 'final', null, 14, 'You are handed a hookload with no operation stated. What is the problem?', '["Pick up, rotating and slack off differ by hundreds of kilonewtons on a deviated well.", "Hookloads are always pick up.", "The hookload depends on the friction factor, which is not stated either, so the number cannot be checked.", "Without the operation the buoyancy factor cannot be applied, since it differs between rotating and tripping."]'::jsonb, 0, 'On the slant well in this course the three differ by half a meganewton. Naming the operation is not optional.'),
  ('torquedrag', 'beginner', 'final', null, 15, 'How much of a deviated well''s surface torque is friction rather than bit torque?', '["About half.", "Around 80 to 90 percent on the wells in this course.", "Nearly all of it, since bit torque is applied at the bit and is attenuated to nothing by the time it reaches surface.", "It depends on the rate of penetration, which sets the bit torque, and cannot be stated without knowing it."]'::jsonb, 1, 'That high friction share is why torque is a better hole-condition indicator than hookload on a long well.'),
  ('torquedrag', 'beginner', 'final', null, 16, 'The engine warns that the hole geometry does not cover the full string. What do you do?', '["Ignore it, it is conservative.", "Refine the step, which will reduce the length of the uncovered interval to below one integration increment.", "Extend the last geometry section to total depth, which the engine would otherwise do automatically.", "Fix the input, because the uncovered interval ran at a friction factor of zero."]'::jsonb, 3, 'A zero friction factor is silently optimistic rather than conservative, and the run is meaningless in that interval.'),
  ('torquedrag', 'beginner', 'final', null, 17, 'Two wells have identical strings and mud. One is 2000 m vertical and one is 2800 m to horizontal. Which has the larger pick-up hookload?', '["The vertical one, by a wide margin.", "They are equal, because the extra string in the lateral contributes no weight along the hole and cancels the friction.", "The horizontal one, but by less than the extra 800 m of string would suggest.", "It cannot be said without the friction factor, since drag can exceed the weight difference at a high enough value."]'::jsonb, 2, 'The lateral adds friction and no axial weight, and the build carries part of the string on the wall, so the two effects partly offset.'),
  ('torquedrag', 'beginner', 'final', null, 18, 'What does a step refinement that changes the answer by a kilonewton tell you?', '["That the default step is not fine enough for that case, and probably that the string is in compression.", "That the model has a bug.", "That the survey interval is too coarse, since the step cannot resolve curvature the stations did not capture.", "That the friction factor is too high, since discretisation error scales with the size of the friction term."]'::jsonb, 0, 'The two cases where it happens in this course are the horizontal well tripping in and sliding, both of which buckle.'),
  ('torquedrag', 'beginner', 'final', null, 19, 'Which operation on a horizontal well has the largest surface torque?', '["Sliding.", "Rotating on bottom.", "Back reaming, because it adds axial motion to the rotation and therefore acts on a larger total sliding velocity.", "Tripping out, because the axial friction is largest there and torque is proportional to the same normal force."]'::jsonb, 1, 'Sliding gives only the bit torque and tripping gives none at all. Back reaming is slightly below rotating on bottom because some friction has moved axially.'),
  ('torquedrag', 'beginner', 'final', null, 20, 'Why is a fitted friction factor not a property of the rock?', '["Because rock has no friction.", "Because it is fitted to a hookload rather than measured in a laboratory, and laboratory values are the real ones.", "Because it varies with depth, and a property of the rock would be constant within a single formation.", "Because it absorbs cuttings, the discarded stiffness, and everything else the model left out."]'::jsonb, 3, 'That is why its TREND is informative even though its VALUE is not transferable between models or software.'),
  ('torquedrag', 'beginner', 'final', null, 21, 'A model shows the tension crossing zero at 1900 m on a vertical well with weight on bit. What is that depth?', '["The casing shoe.", "The top of the buckled interval, which is deeper than the neutral point because buckling needs a finite compression.", "The neutral point, below which the string is in compression.", "The depth at which the buoyed weight of the string below equals the hookload at surface."]'::jsonb, 2, 'In a vertical hole the buckling limits are zero, so the buckling flag sits at the same depth, and it carries no extra information.'),
  ('torquedrag', 'beginner', 'final', null, 22, 'What is the value of a broomstick plot over three numbers?', '["It shows WHERE the drag is being generated, not just how much of it there is.", "It is easier to read.", "It shows the buckling state along the string, which the three summary hookloads do not carry at all.", "It shows the torque as well as the tension, so both constraints can be checked from a single chart."]'::jsonb, 0, 'The gradient of the gap between the curves is the local friction contribution, which the summaries throw away.'),
  ('torquedrag', 'beginner', 'final', null, 23, 'Which two things are identical across all five wells in this course?', '["The total depth and the shoe depth.", "The string and the mud, along with the friction factors and the operating parameters.", "The maximum inclination and the survey interval, so that the geometries can be compared station for station.", "The buoyancy factor and the buoyed string weight, since both depend only on the mud and the steel densities."]'::jsonb, 1, 'The buoyancy factor is shared and the buoyed WEIGHT is not, because the wells have different amounts of drill pipe in them.'),
  ('torquedrag', 'beginner', 'final', null, 24, 'Why does the model treat buoyancy as a single scalar factor?', '["Because it is an approximation.", "Because the pressure at the top and bottom of each component cancels, leaving only the density ratio.", "Because the mud is incompressible, so its density does not change with depth or with temperature.", "Because the string is fully immersed in one fluid, inside and out."]'::jsonb, 3, 'It stops being true the moment the string has different fluids inside and outside it, which is why completion analysis uses a different model.'),
  ('torquedrag', 'beginner', 'final', null, 25, 'A horizontal well''s slide-drilling hookload comes out at -157 kN. What is the practical reading?', '["The slide will be slow but possible.", "The weight on bit will have to be reduced until the hookload is positive, which is a routine adjustment.", "Sliding cannot be done on this well at all, which is why rotary steerables took over extended reach.", "The string will need a heavier bottom hole assembly, which will supply the weight without the pipe being compressed."]'::jsonb, 2, 'The minimum tension on that case is over 400 kN of compression against a buckling limit around a third of it.'),
  ('torquedrag', 'beginner', 'final', null, 26, 'What is the exchange rate a driller controls while back reaming?', '["The ratio of trip speed to tool joint surface speed, which sets how the friction is shared.", "The friction factor.", "The weight on bit, which sets the compression at the bit end and therefore the side force in the lower string.", "The mud weight, which sets the buoyancy factor and therefore how much weight the friction is acting against."]'::jsonb, 0, 'Pull slower and more of the friction goes into torque; pull faster and more stays axial. It is the only lever in the trade.'),
  ('torquedrag', 'beginner', 'final', null, 27, 'Two implementations of the same model disagree by 32 N on a 730 kN hookload. What do you do?', '["Assume both are wrong.", "Note it, check whether refinement closes it, and find a case with a closed form.", "Take the average of the two, since neither can be preferred and the truth is likely to lie between them.", "Use the finer-stepped one, since a higher-order integration scheme is by definition the more accurate."]'::jsonb, 1, 'Refinement separates discretisation from a model difference, and a closed form says which implementation is closer.'),
  ('torquedrag', 'beginner', 'final', null, 28, 'Which of these is a setup error rather than a result?', '["A buckling flag at the neutral point.", "A negative slack-off hookload on a long lateral, which means the string will not descend under its own weight.", "A torsion utilization above the tension utilization, which happens whenever the well is sufficiently deviated.", "A warning that the hole geometry does not cover the full string."]'::jsonb, 3, 'The other three are all correct results that need interpreting. The geometry warning means an input is incomplete.'),
  ('torquedrag', 'beginner', 'final', null, 29, 'What does the model''s trip speed of 0.3 m/s affect?', '["The surge and swab pressures.", "The friction magnitude, which rises with sliding speed as the contact transitions out of the boundary regime.", "Only the direction cosines, and with no rotation it does not affect the answer at all.", "The buckling limits, which depend on the rate at which compression is applied to the string."]'::jsonb, 2, 'That the drag does not depend on trip speed is a real limitation, and it is why surge and swab are a separate calculation.'),
  ('torquedrag', 'beginner', 'final', null, 30, 'Which string component has the highest buoyed weight per metre?', '["The drill collars, at nearly five times the drill pipe''s value.", "The drill pipe, being the longest.", "The heavy weight drill pipe, which is designed to be the transition between the collars and the drill pipe above.", "They are all equal per metre, since buoyancy scales the air weight by the same factor for every component."]'::jsonb, 0, 'That is why the tension profile in a vertical hole is three straight segments with the steepest at the bottom.'),
  ('torquedrag', 'beginner', 'final', null, 31, 'What would make the model''s answers on a lateral optimistic?', '["A step size that is too fine.", "A buckled string, whose contact force and friction are higher than the model assumes.", "A friction factor fitted on the vertical section, which does not include the cuttings beds a lateral accumulates.", "A survey with too few stations, which understates the curvature and therefore the side force along the lateral."]'::jsonb, 1, 'A friction factor fitted elsewhere and a survey with too few stations would also make it optimistic, and the buckling one is the only one the model itself flags.'),
  ('torquedrag', 'beginner', 'final', null, 32, 'How is the vertical well''s hookload computed without an engine?', '["It cannot be, without integration.", "Take the air weight and subtract the volume of the string times the mud density times gravity, which is the same thing.", "Take the buoyed weight and subtract the friction in the cased section, which is the only contact in a vertical hole.", "Sum the component masses, multiply by gravity, multiply by the buoyancy factor."]'::jsonb, 3, 'Subtracting the displaced mud''s weight from the air weight describes the same physics and arrives at the same number, which is a good way to check that the factor is right.'),
  ('torquedrag', 'beginner', 'final', null, 33, 'A driller reports the pick-up drag rising over three connections while slack-off drag holds steady. What does that suggest?', '["The friction factor has risen.", "The mud weight has increased, which raises the buoyed weight and therefore both the hookloads and their difference.", "Something acting asymmetrically, such as a ledge or the start of sticking, rather than general friction.", "The string has got longer, which raises every hookload and therefore raises both drags proportionally."]'::jsonb, 2, 'A general friction rise moves both drags. One moving alone points at a mechanism that cares which way the string is going.'),
  ('torquedrag', 'beginner', 'final', null, 34, 'Why is torque zero while sliding above the motor?', '["Nothing above the motor is turning, so there is no tangential friction anywhere along it.", "Because the bit torque is zero.", "Because the mud motor absorbs the reactive torque, so none of it is transmitted up the string to surface.", "Because sliding is done with the pumps off, and without circulation the bit generates no torque at all."]'::jsonb, 0, 'The surface torque equals the bit torque exactly, and that is true on every well in this course.'),
  ('torquedrag', 'beginner', 'final', null, 35, 'What is the practical use of knowing a vertical hole generates no side force?', '["It means vertical wells need no model.", "The vertical section of any well is essentially free in torque and drag terms.", "It means the friction factor in the cased section is irrelevant, since casing is always set in vertical hole.", "It means a vertical well''s hookload is the air weight, since there is nothing to reduce it below that."]'::jsonb, 1, 'Deep vertical wells are limited by pipe strength rather than by drag, and that is why they can be so deep.'),
  ('torquedrag', 'beginner', 'final', null, 36, 'What happens to the three hookloads as a well''s hold angle increases past about 60 degrees?', '["They all rise, because drag rises.", "Pick up rises and slack off falls, so the swing widens while the rotating value stays at the buoyed weight.", "They converge, because at high angle the friction becomes small compared with the weight along the hole.", "They all fall, because more of the string''s weight is carried by the wall."]'::jsonb, 3, 'The drag keeps growing while the axial weight component shrinks, and the second effect eventually wins.'),
  ('torquedrag', 'beginner', 'final', null, 37, 'Which of these does the buoyancy factor NOT depend on?', '["The mud density.", "The steel density, which is 7850 kg/m3 by default and appears in the denominator of the expression.", "The hole diameter.", "Nothing else at all, since it is one less the ratio of the two densities and takes no other input."]'::jsonb, 2, 'It is a ratio of two densities. Hole size affects the clearance and the buckling limits, and not the buoyancy.'),
  ('torquedrag', 'beginner', 'final', null, 38, 'A model shows a well''s rotating hookload well below its buoyed string weight. Is that right?', '["Yes, on a deviated well, because the axial weight component is w cos(theta) rather than w.", "No, they should be equal.", "Only if the string is partly in compression, which reduces the load the string above the neutral point carries.", "Only if the mud weight used in the model differs from the one used to compute the buoyed weight."]'::jsonb, 0, 'In a vertical well they are equal. In a 40 degree hold they are not, and the gap is the weight the wall is carrying.'),
  ('torquedrag', 'beginner', 'final', null, 39, 'What single check would catch most unit errors in a torque and drag setup?', '["Comparing torque against hookload.", "The vertical case against the hand-computed buoyed weight.", "Running the same well at two friction factors and confirming the hookload moves in the expected direction.", "Checking that the buckling flags appear where the tension crosses zero, which they should on any vertical well."]'::jsonb, 1, 'It exercises the string description, the mud, the gravity constant and the depth grid in one run.'),
  ('torquedrag', 'beginner', 'final', null, 40, 'Why do six operations produce only two distinct torques on a vertical well?', '["Because torque is not computed there.", "Because the tangential cosine is zero everywhere in a vertical hole, so no operation can produce friction torque.", "Because rotating off bottom and rotating on bottom give the same torque once the bit torque is subtracted.", "Zero for the four with no bit torque, and the bit torque for the two on bottom."]'::jsonb, 3, 'There is no side force anywhere, so the friction torque is zero regardless of rotation. Only the boundary condition survives.'),
  ('torquedrag', 'beginner', 'final', null, 41, 'What is the honest one-line description of this tier''s output?', '["The loads the string will actually see.", "The hookload and torque a driller will read at surface, which the model reproduces to within a few percent.", "The loads a soft-string model gives on a stated geometry at a stated friction factor.", "The friction between the string and the hole, which the model measures from the survey and the string description."]'::jsonb, 2, 'Each of the wrong answers claims more than the model delivers, and the differences between them and the right one are what the next two tiers are about.'),
  ('torquedrag', 'beginner', 'final', null, 42, 'A well plan shows a comfortable hookload and a torque near the top drive''s rating. Which do you redesign for?', '["The torque, because it is the one at a limit and the hookload has margin to spare.", "The hookload, since it sets the derrick.", "Both, because the two are coupled through the same friction force and reducing one necessarily reduces the other.", "Neither: the plan is acceptable as long as each individual load is below its own rating with a margin."]'::jsonb, 0, 'They are coupled through the friction and not proportionally, and the levers that reduce torque are not the ones that reduce hookload.');
